"""Document/source checks only. No replay, evaluator or acceptance."""
from pathlib import Path
import collections
import datetime
import difflib
import hashlib
import json
import subprocess
import traceback

R = Path('F:/ChnobelRuntime/reviews/v2-manifest-questions-03/u07')
M = Path('F:/ChnobelRuntime/specification/v2-manifest-draft-01')
P = Path('F:/Projects/Chnobel')
O = Path(__file__).parent
BASE = 'f6e73092dd1d5940506c145d645917abc601f1a6'
DISPATCH_BASE = '229fb3bd52f0473af5aeb9ead023df3db63c6847'
INPUT_BASE = '299cea2c502a370e4128bb2bd77d48787e4c7dcc'


def sha(raw): return hashlib.sha256(raw).hexdigest()
def load(p): return json.loads(Path(p).read_bytes())
def bind(p):
    p = Path(p); raw = p.read_bytes()
    return {'path': p.as_posix(), 'sha256': sha(raw), 'bytes': len(raw)}
def proj(b): return {k: Path(b[k]).as_posix() if k == 'path' else b[k] for k in ('path', 'sha256', 'bytes')}
def check(b): assert bind(b['path']) == proj(b), b['path']
def rawcheck(raw, b): assert sha(raw) == b['sha256'] and len(raw) == b['bytes'], b['path']
def git(*a): return subprocess.check_output(['git', '-C', str(P), *a])
def ptr(value, address):
    for p in address.split('/')[1:]:
        p = p.replace('~1', '/').replace('~0', '~')
        value = value[int(p)] if isinstance(value, list) else value[p]
    return value
def save(name, obj):
    with (O / name).open('x', encoding='utf-8', newline='\n') as f:
        json.dump(obj, f, ensure_ascii=False, indent=2); f.write('\n')


def main():
    assert git('rev-parse', 'HEAD').decode().strip() == BASE
    assert not git('status', '--porcelain=v1', '--untracked-files=all')
    d, s, inputs = load(R / 'redteam/decision.json'), load(R / 'redteam/sources.json'), load(R / 'input-bindings.json')
    assert {p.name for p in (R / 'redteam').iterdir()} == {'report.md', 'sources.json', 'decision.json'}
    assert bind(R / 'redteam/decision.json')['sha256'] == '2fea87377870735ac7f1939f1bea1d3e2d9af53449d78d8538873c16fbda0f15'
    for k in ('report', 'sources', 'brief', 'input', 'proceduralFreeze', 'manifest'): check(d[k])
    procedural = load(d['proceduralFreeze']['path'])
    assert s['inputObject'] == inputs and s['proceduralFreezeObject'] == procedural
    assert d['brief']['sha256'] == 'e26814fe066372316a2e5a1a0d80ee81391e0eadd2a48e46aade902b33bb9231'
    assert d['input']['sha256'] == '9878ae90f1cbb6c0df5af7b26460fd60b6911f3ab4115cf51d9200c19986aba0'
    assert d['proceduralFreeze']['sha256'] == 'c25dbac2a0c8e757ab5f7f3b64a80850f27510da1e39bf5d996e0acc8f858d28'
    assert d['role'] == 'redteam' and d['questionId'] == 'Q-U07' and d['scopeStatus'] == 'COMPLETE'
    assert set(d['sectionAssessments']) == {'Q1', 'Q2', 'Q3', 'Q4', 'Q5', 'Q6'}
    assert all(x['status'] == 'COMPLETE' for x in d['sectionAssessments'].values())
    assert d['wholeRoleStatus'] == 'INCOMPLETE_OTHER_QUESTIONS_PENDING' and d['wholeManifestVerdict'] == 'NOT_ISSUED'
    assert not any(d[k] for k in ('implementationAuthorized', 'blockerClosed', 'ratificationIssued', 'integrationAuthorized', 'releaseAuthorized', 'selfApproval'))
    assert d['recommendation']['adoptionStatus'] == 'PROPOSED_NOT_ACCEPTED' and not d['recommendation']['unconditionalAcceptance']
    assert all(d[k] == 'NOT_RUN' for k in ('productExecution', 'schemaExecution', 'evaluatorExecution', 'testsExecution', 'nativeExecution', 'oracleExecution'))
    words = len((R / 'redteam/report.md').read_text(encoding='utf-8').split())
    assert words == d['reportWordCount'] and words <= 1400
    required = {b['path']: b for b in inputs['mandatoryFiles']}
    additional = {b['path']: proj(b) for b in [d['brief'], d['input'], d['proceduralFreeze']] + procedural['additionalProceduralSources']}
    assert len(required) == 53 and len(additional) == 6
    for name, expected in [('mandatoryFiles', required), ('additionalSources', additional)]:
        assert len(s[name]) == len(expected) and {b['expected']['path'] for b in s[name]} == set(expected)
        for entry in s[name]:
            for phase in ('expected', 'before', 'after'):
                assert proj(entry[phase]) == proj(expected[entry['expected']['path']])
                check(entry[phase])
            assert entry['readScope'] and entry['matchBeforeAndAfter'] is True
    for b in procedural['additionalProceduralSources']:
        assert b['utf8Raw'].encode('utf-8') == Path(b['path']).read_bytes()
    assert d['proceduralExceptions'] == s['incidents'] and len(s['incidents']) == 3
    assert {x['id'] for x in s['incidents']} == {'DOC-OUTPUT-01', 'DOC-SHELL-02', 'DOC-SHELL-03'}
    contexts, changed = 0, 0
    input_contexts = {b['path']: b for b in inputs['mutableContextsBefore']}
    dispatch_contexts = {b['path']: b for b in procedural['mutableParentContextsAtDispatch']}
    assert len(s['mutableParentContexts']) == 3
    for c in s['mutableParentContexts']:
        path = c['path']; relative = Path(path).relative_to(P).as_posix()
        assert c['inputBaseline'] == input_contexts[path] and c['dispatchBaseline'] == dispatch_contexts[path]
        raws = {'input': c['inputBaseline']['beforeUtf8'].encode('utf-8'), 'dispatch': c['dispatchBaseline']['utf8Raw'].encode('utf-8'), 'before': c['before']['utf8Raw'].encode('utf-8'), 'after': c['after']['utf8Raw'].encode('utf-8')}
        rawcheck(raws['input'], c['expected']); rawcheck(raws['dispatch'], c['dispatchExpected'])
        rawcheck(raws['before'], c['before']); rawcheck(raws['after'], c['after'])
        assert raws['before'] == raws['dispatch'] and raws['after'] == Path(path).read_bytes()
        for stage, commit in [('input', INPUT_BASE), ('dispatch', DISPATCH_BASE), ('after', BASE)]:
            assert git('show', commit + ':' + relative) == raws[stage].replace(b'\r\n', b'\n')
        assert len(c['diffs']) == 3
        for diff in c['diffs']:
            left, right = diff['stage'].split('_to_')
            assert ''.join(difflib.restore(diff['lines'], 1)).encode('utf-8') == raws[left]
            assert ''.join(difflib.restore(diff['lines'], 2)).encode('utf-8') == raws[right]
            rawcheck(raws[left], diff['from']); rawcheck(raws[right], diff['to'])
            assert diff['changed'] == (raws[left] != raws[right])
            contexts += 1; changed += diff['changed']
    projections = inputs['selectedCases'] + inputs['transportVariants']
    by_pointer = {(b['index']['path'], b['pointer']): b for b in projections}
    assert len(s['originalIndexProjections']) == len(by_pointer) == 12
    for x in s['originalIndexProjections']:
        original = by_pointer[(x['index']['path'], x['pointer'])]
        assert x['expectedOriginalRecord'] == x['observedOriginalRecord'] == original['originalRecord'] == ptr(load(x['index']['path']), x['pointer'])
        assert len(x['targetBindings']) == 2
        for b in x['targetBindings']:
            assert b['originalBinding'] == original['originalRecord'][b['field']]
            assert b['absoluteTarget'] == original[b['field']]; check(b['absoluteTarget'])
    for x in s['historicalCaseProjections']:
        assert ptr(load(x['index']['path']), x['pointer']) == x['originalRecord']
        check(x['selectedCopy']); check(x['archiveCopy'])
        assert Path(x['selectedCopy']['path']).read_bytes() == Path(x['archiveCopy']['path']).read_bytes()
        assert x['originalRecord']['sha256'] == x['selectedCopy']['sha256']
    handoff = load(inputs['manifestHandoff']['path']); hp = s['handoffProjection']
    check(hp['source']); assert hp['source'] == inputs['manifestHandoff']
    assert len(handoff['files']) == hp['inventoryCount'] == 4944
    assert len(hp['records']) == hp['selectedTargetCount'] == 38
    for x in hp['records']:
        assert ptr(handoff, x['pointer']) == x['originalRecord']; check(x['target'])
        assert (M / x['originalRecord']['path']).as_posix() == x['target']['path']
        assert all(x['originalRecord'][k] == x['target'][k] for k in ('sha256', 'bytes'))
    base_cases = {b['caseId']: b for b in inputs['selectedCases']}
    variant_records = {b['caseId']: b for b in inputs['transportVariants']}
    assert len(s['transportChecks']) == 8
    for x in s['transportChecks']:
        base = base_cases[x['baseCaseId']]; vr = variant_records[x['caseId']]
        assert x['input'] == vr['input'] and x['oracle'] == vr['oracle'] and x['baseOracle'] == base['oracle']
        inp, baseinp, oracle, baseoracle = load(x['input']['path']), load(base['input']['path']), load(x['oracle']['path']), load(base['oracle']['path'])
        eventmap = {e['eventId']: e for e in baseinp['events']}; events = inp['events']
        assert all(e == eventmap[e['eventId']] for e in events)
        assert {e['eventId'] for e in events} == set(eventmap)
        assert x['deliveredSeqOrder'] == [e['seq'] for e in events]
        counts = {'delivered': len(events), 'uniqueIds': len(eventmap), 'duplicateDeliveries': len(events) - len(eventmap)}
        assert counts == x['counts']
        assert {k: v for k, v in inp.items() if k not in ('events', 'caseId')} == {k: v for k, v in baseinp.items() if k not in ('events', 'caseId')}
        diffs = {k for k in set(oracle) | set(baseoracle) if oracle.get(k) != baseoracle.get(k)}
        assert diffs == set(x['oracleDifferingFields'])
        assert x['oracleTransportValues'] == {k: oracle[k] for k in diffs}
    catalogue, rules = load(M / 'catalogue.json'), load(M / 'rule-records.json')
    facts = {x['id'] for x in catalogue['facts']}; claimids = {x['claimId'] for x in rules}
    event_refs, help_refs = 0, 0
    for case in d['cases'] + d['boundaryControls']:
        base = base_cases[case['caseId']]; assert case['input'] == base['input']
        original = load(base['input']['path'])
        for observed in case['eventReferences']:
            actual = ptr(original, observed['pointer'])
            assert all(actual[k] == v for k, v in observed.items() if k != 'pointer')
        if case in d['cases']:
            event_refs += len(case['eventReferences'])
            assert case['existingOracle'] == base['oracle']
            assert {x['factId'] for x in case['factRecommendations']} == facts
            assert {x['claimId'] for x in case['claimRecommendations']} == claimids
            for x in case['factRecommendations']:
                assert ptr(catalogue, x['normPointer'].split('#', 1)[1])['id'] == x['factId']
            for x in case['claimRecommendations']:
                rule = ptr(rules, x['rulePointer'].split('#', 1)[1])
                assert rule['id'] == x['ruleId'] and rule['claimId'] == x['claimId']
            for observed in case['supportEvidenceReferences']:
                actual = ptr(original, observed['pointer'])
                assert all(actual[k] == v for k, v in observed.items() if k != 'pointer')
            help_refs += len(case['supportEvidenceReferences'])
            proof = case['proofReferencesProposal']['attempt.result.correct']
            assert [ptr(original, p)['eventId'] for p in proof['eventPointers']] == proof['eventIds']
            assert case['fullNewOracleIssued'] is False and case['semanticOracleAccepted'] is False
    assert event_refs == 16 and help_refs == 14
    summary = s['verificationSummary']; assert summary == d['documentVerification']
    assert contexts == summary['rawContextTransitionsVerified'] == 9 and changed == summary['changedRawContextTransitions'] == 6
    scopes = dict(collections.Counter(x['readScope']['semantic'] for x in s['mandatoryFiles']))
    assert scopes == summary['mandatorySemanticReadScopes']
    previous = load('F:/ChnobelRuntime/verification/u07-question-03-parent/verification.json')
    roles = {}
    for role in ('didaktik', 'architekt', 'redteam'):
        decision = load(R / role / 'decision.json')
        assert decision['scopeStatus'] == 'COMPLETE' and decision['wholeRoleStatus'] == 'INCOMPLETE_OTHER_QUESTIONS_PENDING'
        assert decision['wholeManifestVerdict'] == 'NOT_ISSUED' and decision['implementationAuthorized'] is False
        if role != 'redteam':
            for b in previous['roles'][role]['outputs']: check(b)
        roles[role] = {'outputs': [bind(R / role / f) for f in ('report.md', 'sources.json', 'decision.json')], 'scopeStatus': decision['scopeStatus'], 'recommendationId': decision['recommendation']['id'], 'normativeClassification': decision['normativeClassification'], 'wholeRoleStatus': decision['wholeRoleStatus'], 'recommendationAccepted': False}
    assert len(roles) == 3
    for b in inputs['mandatoryFiles']: check(b)
    assert not git('status', '--porcelain=v1', '--untracked-files=all')
    result = {'result': 'PASS_DOCUMENT_BINDINGS_WITH_RETAINED_TOOL_EXCEPTIONS', 'scope': 'REDTEAM_DOCUMENT_AND_SOURCE_MECHANICS_PLUS_PRIOR_OUTPUT_READBACK_ONLY', 'at': datetime.datetime.now().astimezone().isoformat(), 'base': BASE, 'helper': bind(__file__), 'roles': roles, 'redteamMandatorySources': 53, 'redteamAdditionalImmutableSources': 6, 'originalIndexProjections': 12, 'historicalIndexProjections': len(s['historicalCaseProjections']), 'selectedHandoffRecords': 38, 'transportLinks': 8, 'contextTransitions': contexts, 'changedContextTransitions': changed, 'primaryEventReferences': event_refs, 'primarySupportEvidenceReferences': help_refs, 'redteamReportWords': words, 'proceduralExceptionsPreserved': s['incidents'], 'sourceLocationClarification': 'DOC-OUTPUT-01 original input object is in sources.json#/inputObject, not decision.json; no raw capture used as norm.', 'priorProceduralDriftUnchanged': True, 'wholeReadSetAtomic': False, 'wholeManifestVerdict': 'NOT_ISSUED', 'implementationAuthorized': False, 'blockerClosed': False, 'productExecution': 'NOT_RUN', 'nativeExecution': 'NOT_RUN'}
    save('verification.json', result)
    print(json.dumps({k: v for k, v in result.items() if k not in ('roles', 'proceduralExceptionsPreserved')}, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    try: main()
    except Exception:
        n = 1
        while (O / f'attempt-{n:02d}.json').exists(): n += 1
        raw = Path(__file__).read_bytes()
        save(f'attempt-{n:02d}.json', {'result': 'DOCUMENT_HELPER_FAILURE_NOT_PRODUCT_VERDICT', 'helperSha256': sha(raw), 'helperUtf8': raw.decode('utf-8'), 'traceback': traceback.format_exc()})
        raise
